1	'use client';
2	
3	import { resolveCollaborationViewers } from '@/components/Collaboration/collaboration-user';
4	import {
5	    useCollaborationCurrentUserId,
6	    useCollaborationUserProfile,
7	} from '@/components/Collaboration/use-collaboration-user';
8	import { QueryKeys } from '@/constants/query-keys';
9	import { DuePriorityLevel, DuePriorityLevelLabels } from '@/enums/dueDiligence';
10	import { sendToastMessage } from '@/functions/messages/toastMessage';
11	import { useSetDuePriorityMutation } from '@/hooks/mutations/due-diligence';
12	import {
13	    useLiquidacaoBoardCollaboration,
14	    type LiquidacaoBoardViewer,
15	} from '@/hooks/useLiquidacaoBoardCollaboration';
16	import { useUserInfoStore } from '@/store/userInfo';
17	import { useQuery, useQueryClient } from '@tanstack/react-query';
18	import { useCallback, useMemo, useState } from 'react';
19	import { LIQUIDACAO_KANBAN_PHASES } from '../constants/liquidacaoKanbanPipeline';
20	import { useOperationalListFilterQueryState } from '../hooks/useOperationalListFilterQueryState';
21	import type {
22	    IKanbanCardSubstatusPill,
23	    ILiquidacaoCardKanban,
24	    TSubstatusKanbanBoardResponse,
25	} from '../interfaces/liquidacaoKanban';
26	import type { ISubstatusKanbanService } from '../interfaces/services';
27	import { buildKanbanCardSubstatusPills } from '../utils/DueLiquidacao/buildKanbanCardSubstatusPills';
28	import { patchSubstatusKanbanBoardAfterPriority } from '../utils/DueLiquidacao/patchSubstatusKanbanBoard';
29	import {
30	    resolveKanbanCardCessionariosStrip,
31	    resolveKanbanCardCurrentSubstatusEnteredAt,
32	    resolveKanbanCardSubstatusTempoUrgente,
33	} from '../utils/DueLiquidacao/resolveKanbanCardPresentation';
34	import {
35	    boardViewersSignature,
36	    normalizeBoardViewer,
37	    sortBoardViewers,
38	} from '../utils/DueLiquidacao/substatusKanbanViewers';
39	
40	export interface IUseViewModelSubstatusKanbanParams {
41	    service: ISubstatusKanbanService;
42	}
43	
44	export interface ISubstatusKanbanBoardColumnView {
45	    id: string;
46	    name: string;
47	    cards: ILiquidacaoCardKanban[];
48	}
49	
50	const BOARD_STALE_TIME_MS = 30_000;
51	
52	function resolveFallbackBoardColumns(): ISubstatusKanbanBoardColumnView[] {
53	    return LIQUIDACAO_KANBAN_PHASES.map((phase) => ({
54	        id: phase.id,
55	        name: phase.label,
56	        cards: [],
57	    }));
58	}
59	
60	function mapBoardColumns(
61	    columns: TSubstatusKanbanBoardResponse['columns'] | undefined,
62	): ISubstatusKanbanBoardColumnView[] {
63	    if (!columns?.length) {
64	        return resolveFallbackBoardColumns();
65	    }
66	
67	    return columns.map((column) => ({
68	        id: column.id,
69	        name: column.name,
70	        cards: column.cards,
71	    }));
72	}
73	
74	export function resolveSubstatusKanbanBoardTotalLabel(total: number): string {
75	    const noun = total === 1 ? 'operação' : 'operações';
76	    return `${total} ${noun} no quadro · clique no card para abrir a liquidação · atualizações em tempo real`;
77	}
78	
79	function boardContainsDueId(
80	    board: TSubstatusKanbanBoardResponse | undefined,
81	    dueId: string,
82	): boolean {
83	    if (!board?.columns) {
84	        return false;
85	    }
86	
87	    return board.columns.some((column) =>
88	        column.cards.some((card) => String(card.id) === String(dueId)),
89	    );
90	}
91	
92	export function useViewModelSubstatusKanban({ service }: IUseViewModelSubstatusKanbanParams) {
93	    const queryClient = useQueryClient();
94	    const setDuePriorityMutation = useSetDuePriorityMutation();
95	    const currentUserId = useCollaborationCurrentUserId();
96	    const userProfile = useCollaborationUserProfile();
97	    const currentUsername = useUserInfoStore(
98	        (state) => state.data.username || state.data.user,
99	    );
100	    const { liquidacaoListApiFilters, listQueryFingerprint } = useOperationalListFilterQueryState();
101	    const [updatingPriorityId, setUpdatingPriorityId] = useState<string | null>(null);
102	
103	    const boardQueryKey = useMemo(
104	        () =>
105	            [
106	                QueryKeys.dueDiligence.substatusKanbanData,
107	                listQueryFingerprint,
108	                currentUsername,
109	            ] as const,
110	        [currentUsername, listQueryFingerprint],
111	    );
112	
113	    const { data, isLoading, isFetching, refetch } = useQuery({
114	        queryKey: boardQueryKey,
115	        queryFn: () => service.getBoard(liquidacaoListApiFilters),
116	        staleTime: BOARD_STALE_TIME_MS,
117	        placeholderData: (previousData) => previousData,
118	    });
119	
120	    const boardColumns = useMemo(
121	        () => mapBoardColumns(data?.columns),
122	        [data?.columns],
123	    );
124	
125	    const columns = useMemo(
126	        () => boardColumns.map((column) => ({ id: column.id, name: column.name })),
127	        [boardColumns],
128	    );
129	
130	    const columnHeatById = useMemo(() => {
131	        const heatById: Record<
132	            string,
133	            TSubstatusKanbanBoardResponse['columns'][number]['heat_summary']
134	        > = {};
135	        data?.columns?.forEach((column) => {
136	            if (column.heat_summary) {
137	                heatById[column.id] = column.heat_summary;
138	            }
139	        });
140	        return heatById;
141	    }, [data?.columns]);
142	
143	    const [viewers, setViewers] = useState<LiquidacaoBoardViewer[]>([]);
144	
145	    const handleViewersSnapshot = useCallback(
146	        (nextViewers: LiquidacaoBoardViewer[]) => {
147	            setViewers((previous) => {
148	                const normalized = sortBoardViewers(nextViewers, currentUserId);
149	                if (boardViewersSignature(previous) === boardViewersSignature(normalized)) {
150	                    return previous;
151	                }
152	                return normalized;
153	            });
154	        },
155	        [currentUserId],
156	    );
157	
158	    const handleBoardRefresh = useCallback(() => {
159	        void refetch();
160	    }, [refetch]);
161	
162	    const { isConnected } = useLiquidacaoBoardCollaboration({
163	        enabled: Boolean(currentUserId),
164	        currentUserId,
165	        onViewers: handleViewersSnapshot,
166	        onViewerJoined: (viewer) => {
167	            const normalized = normalizeBoardViewer(viewer);
168	            setViewers((previous) => {
169	                const index = previous.findIndex((entry) => entry.user_id === normalized.user_id);
170	                const merged =
171	                    index === -1
172	                        ? [...previous, normalized]
173	                        : previous.map((entry, entryIndex) =>
174	                              entryIndex === index ? normalized : entry,
175	                          );
176	                return sortBoardViewers(merged, currentUserId);
177	            });
178	        },
179	        onViewerLeft: (userId) => {
180	            setViewers((previous) => previous.filter((entry) => entry.user_id !== String(userId)));
181	        },
182	        onCardMoved: handleBoardRefresh,
183	        onPriorityChanged: handleBoardRefresh,
184	        onSlaConfigChanged: handleBoardRefresh,
185	        onDueStateChanged: handleBoardRefresh,
186	    });
187	
188	    const displayViewers = useMemo(
189	        () =>
190	            sortBoardViewers(
191	                resolveCollaborationViewers(
192	                    viewers,
193	                    userProfile,
194	                    isConnected,
195	                ) as LiquidacaoBoardViewer[],
196	                currentUserId,
197	            ),
198	        [currentUserId, isConnected, userProfile, viewers],
199	    );
200	
201	    const buildCardPills = useCallback(
202	        (card: ILiquidacaoCardKanban, columnId: string): IKanbanCardSubstatusPill[] =>
203	            buildKanbanCardSubstatusPills({ card, columnId }),
204	        [],
205	    );
206	
207	    const handlePriorityChange = useCallback(
208	        async (dueId: string, level: DuePriorityLevel | null) => {
209	            const previousBoard = queryClient.getQueryData<TSubstatusKanbanBoardResponse>(
210	                boardQueryKey,
211	            );
212	
213	            if (!boardContainsDueId(previousBoard, dueId)) {
214	                return;
215	            }
216	
217	            queryClient.setQueryData<TSubstatusKanbanBoardResponse>(boardQueryKey, (currentBoard) =>
218	                patchSubstatusKanbanBoardAfterPriority(currentBoard, dueId, level),
219	            );
220	            setUpdatingPriorityId(dueId);
221	
222	            try {
223	                await setDuePriorityMutation.mutateAsync({ dueId, priorityLevel: level });
224	                sendToastMessage({
225	                    type: 'success',
226	                    title: level
227	                        ? `Prioridade ${DuePriorityLevelLabels[level]} aplicada`
228	                        : 'Prioridade removida',
229	                });
230	            } catch {
231	                queryClient.setQueryData(boardQueryKey, previousBoard);
232	                sendToastMessage({ type: 'error', title: 'Erro ao alterar prioridade.' });
233	            } finally {
234	                setUpdatingPriorityId(null);
235	            }
236	        },
237	        [boardQueryKey, queryClient, setDuePriorityMutation],
238	    );
239	
240	    const total = data?.total ?? 0;
241	
242	    return {
243	        ui: {
244	            isLoading: isLoading && !data,
245	            isFetching,
246	            total,
247	            isEmpty: total === 0,
248	            columns,
249	            boardColumns,
250	            columnHeatById,
251	            viewers: displayViewers,
252	            isConnected,
253	            currentUserId,
254	            updatingPriorityId,
255	        },
256	        handlers: {
257	            refetch,
258	            buildCardPills,
259	            resolveCardSubstatusEnteredAt: resolveKanbanCardCurrentSubstatusEnteredAt,
260	            isCardSubstatusTempoUrgente: (card: ILiquidacaoCardKanban) =>
261	                resolveKanbanCardSubstatusTempoUrgente(
262	                    resolveKanbanCardCurrentSubstatusEnteredAt(card),
263	                ),
264	            getCardCessionarios: resolveKanbanCardCessionariosStrip,
265	            onPriorityChange: handlePriorityChange,
266	        },
267	        constants: {
268	            phases: LIQUIDACAO_KANBAN_PHASES,
269	            boardTotalLabel: resolveSubstatusKanbanBoardTotalLabel(total),
270	        },
271	    };
272	}
273

