    boardViewersSignature,
    normalizeBoardViewer,
    sortBoardViewers,
} from '../utils/DueLiquidacao/substatusKanbanViewers';

export interface IUseViewModelSubstatusKanbanParams {
    service: ISubstatusKanbanService;
}

export interface ISubstatusKanbanBoardColumnView {
    id: string;
    name: string;
    cards: ILiquidacaoCardKanban[];
}

const BOARD_STALE_TIME_MS = 30_000;

function resolveFallbackBoardColumns(): ISubstatusKanbanBoardColumnView[] {
    return LIQUIDACAO_KANBAN_PHASES.map((phase) => ({
        id: phase.id,
        name: phase.label,
        cards: [],
    }));
}

function mapBoardColumns(
    columns: TSubstatusKanbanBoardResponse['columns'] | undefined,
): ISubstatusKanbanBoardColumnView[] {
    if (!columns?.length) {
        return resolveFallbackBoardColumns();
    }

    return columns.map((column) => ({
        id: column.id,
        name: column.name,
        cards: column.cards,
    }));
}

export function resolveSubstatusKanbanBoardTotalLabel(total: number): string {
    const noun = total === 1 ? 'operação' : 'operações';
    return `${total} ${noun} no quadro · clique no card para abrir a liquidação · atualizações em tempo real`;
}

function boardContainsDueId(
    board: TSubstatusKanbanBoardResponse | undefined,
    dueId: string,
): boolean {
    if (!board?.columns) {
        return false;
    }

    return board.columns.some((column) =>
        column.cards.some((card) => String(card.id) === String(dueId)),
    );
}

export function useViewModelSubstatusKanban({ service }: IUseViewModelSubstatusKanbanParams) {
    const queryClient = useQueryClient();
    const setDuePriorityMutation = useSetDuePriorityMutation();
    const currentUserId = useCollaborationCurrentUserId();
    const userProfile = useCollaborationUserProfile();
    const currentUsername = useUserInfoStore(
        (state) => state.data.username || state.data.user,
    );
    const { liquidacaoListApiFilters, listQueryFingerprint } = useOperationalListFilterQueryState();
    const [updatingPriorityId, setUpdatingPriorityId] = useState<string | null>(null);

    const boardQueryKey = useMemo(
        () =>
            [
                QueryKeys.dueDiligence.substatusKanbanData,
                listQueryFingerprint,
                currentUsername,
            ] as const,
        [currentUsername, listQueryFingerprint],
    );

    const { data, isLoading, isFetching, refetch } = useQuery({
        queryKey: boardQueryKey,
        queryFn: () => service.getBoard(liquidacaoListApiFilters),
        staleTime: BOARD_STALE_TIME_MS,
        placeholderData: (previousData) => previousData,
    });

    const boardColumns = useMemo(
        () => mapBoardColumns(data?.columns),
        [data?.columns],
    );

    const columns = useMemo(
        () => boardColumns.map((column) => ({ id: column.id, name: column.name })),
        [boardColumns],
    );

    const columnHeatById = useMemo(() => {
        const heatById: Record<
            string,
            TSubstatusKanbanBoardResponse['columns'][number]['heat_summary']
        > = {};
        data?.columns?.forEach((column) => {
            if (column.heat_summary) {
                heatById[column.id] = column.heat_summary;
            }
        });
        return heatById;
    }, [data?.columns]);

    const [viewers, setViewers] = useState<LiquidacaoBoardViewer[]>([]);

    const handleViewersSnapshot = useCallback(
        (nextViewers: LiquidacaoBoardViewer[]) => {
            setViewers((previous) => {
                const normalized = sortBoardViewers(nextViewers, currentUserId);
                if (boardViewersSignature(previous) === boardViewersSignature(normalized)) {
                    return previous;
                }
                return normalized;
            });
        },
        [currentUserId],
    );

    const handleBoardRefresh = useCallback(() => {
        void refetch();
    }, [refetch]);

    const { isConnected } = useLiquidacaoBoardCollaboration({
        enabled: Boolean(currentUserId),
        currentUserId,
        onViewers: handleViewersSnapshot,
        onViewerJoined: (viewer) => {
            const normalized = normalizeBoardViewer(viewer);
            setViewers((previous) => {
                const index = previous.findIndex((entry) => entry.user_id === normalized.user_id);
                const merged =
                    index === -1
                        ? [...previous, normalized]
                        : previous.map((entry, entryIndex) =>
                              entryIndex === index ? normalized : entry,
                          );
                return sortBoardViewers(merged, currentUserId);
            });
        },
        onViewerLeft: (userId) => {
            setViewers((previous) => previous.filter((entry) => entry.user_id !== String(userId)));
        },
        onCardMoved: handleBoardRefresh,
        onPriorityChanged: handleBoardRefresh,
        onSlaConfigChanged: handleBoardRefresh,
        onDueStateChanged: handleBoardRefresh,
    });

    const displayViewers = useMemo(
        () =>
            sortBoardViewers(
                resolveCollaborationViewers(
                    viewers,
                    userProfile,
                    isConnected,
                ) as LiquidacaoBoardViewer[],
                currentUserId,
            ),
        [currentUserId, isConnected, userProfile, viewers],
    );

    const buildCardPills = useCallback(
        (card: ILiquidacaoCardKanban, columnId: string): IKanbanCardSubstatusPill[] =>
            buildKanbanCardSubstatusPills({ card, columnId }),
        [],
    );

    const handlePriorityChange = useCallback(
        async (dueId: string, level: DuePriorityLevel | null) => {
            const previousBoard = queryClient.getQueryData<TSubstatusKanbanBoardResponse>(
                boardQueryKey,
            );

            if (!boardContainsDueId(previousBoard, dueId)) {
                return;
            }

            queryClient.setQueryData<TSubstatusKanbanBoardResponse>(boardQueryKey, (currentBoard) =>
                patchSubstatusKanbanBoardAfterPriority(currentBoard, dueId, level),
            );
            setUpdatingPriorityId(dueId);

            try {
                await setDuePriorityMutation.mutateAsync({ dueId, priorityLevel: level });
                sendToastMessage({
                    type: 'success',
                    title: level
                        ? `Prioridade ${DuePriorityLevelLabels[level]} aplicada`
                        : 'Prioridade removida',
                });
            } catch {
                queryClient.setQueryData(boardQueryKey, previousBoard);
                sendToastMessage({ type: 'error', title: 'Erro ao alterar prioridade.' });
            } finally {
                setUpdatingPriorityId(null);
            }
        },
        [boardQueryKey, queryClient, setDuePriorityMutation],
    );

    const total = data?.total ?? 0;

    return {
        ui: {
            isLoading: isLoading && !data,
            isFetching,
            total,
            isEmpty: total === 0,
            columns,
            boardColumns,
            columnHeatById,
            viewers: displayViewers,
            isConnected,
            currentUserId,
            updatingPriorityId,
        },
        handlers: {
            refetch,
            buildCardPills,
            resolveCardSubstatusEnteredAt: resolveKanbanCardCurrentSubstatusEnteredAt,
            isCardSubstatusTempoUrgente: (card: ILiquidacaoCardKanban) =>
                resolveKanbanCardSubstatusTempoUrgente(
                    resolveKanbanCardCurrentSubstatusEnteredAt(card),
                ),
            getCardCessionarios: resolveKanbanCardCessionariosStrip,
            onPriorityChange: handlePriorityChange,
        },
        constants: {
            phases: LIQUIDACAO_KANBAN_PHASES,
            boardTotalLabel: resolveSubstatusKanbanBoardTotalLabel(total),
        },
    };
}

