'use client';

import { DUE_ACTIVE_VIEW_TABS_STALE_MS } from '@/constants/due-diligence-query';
import { QueryKeys } from '@/constants/query-keys';
import { useQuery } from '@tanstack/react-query';
import gsap from 'gsap';
import { useLayoutEffect, useMemo, useRef } from 'react';
import {
    DUE_STATISTICS_SUMMARY_CARD_SELECTOR,
    DUE_STATISTICS_SUMMARY_ENTRY_BLUR_PX,
    DUE_STATISTICS_SUMMARY_ENTRY_DURATION_S,
    DUE_STATISTICS_SUMMARY_ENTRY_STAGGER_S,
    DUE_STATISTICS_SUMMARY_ENTRY_X_PERCENT,
} from '../constants/due-statistics-summary-animation';
import { ActiveViewType } from '../enums';
import { useDueDiligenceActiveView } from '../hooks/use-due-diligence-active-view';
import { useOperationalListFilterQueryState } from '../hooks/useOperationalListFilterQueryState';
import type { IDueDiligenceStatisticsService } from '../interfaces/services';
import { buildDueDiligenceStatisticsRql } from '../utils/buildDueDiligenceStatisticsRql';

export function useViewModelDueDiligenceStatistics(service: IDueDiligenceStatisticsService) {
    const { activeView } = useDueDiligenceActiveView();
    const { operationalListApiFilters, modeloScope, toggleModelo } =
        useOperationalListFilterQueryState();
    const summaryCardsContainerRef = useRef<HTMLElement | null>(null);

    const rql = useMemo(
        () => buildDueDiligenceStatisticsRql(activeView, operationalListApiFilters),
        [activeView, operationalListApiFilters],
    );

    const isEnabled =
        activeView === ActiveViewType.DUE_DILIGENCE || activeView === ActiveViewType.LIQUIDACAO;

    const { data, isLoading } = useQuery({
        queryKey: [QueryKeys.dueDiligence.listSummary, activeView, rql],
        queryFn: () => service.getSummary(rql),
        enabled: isEnabled,
        staleTime: DUE_ACTIVE_VIEW_TABS_STALE_MS,
    });

    useLayoutEffect(() => {
        const container = summaryCardsContainerRef.current;
        if (!container) return;

        const cards = container.querySelectorAll(DUE_STATISTICS_SUMMARY_CARD_SELECTOR);
        if (cards.length === 0) return;

        const media = gsap.matchMedia();

        media.add('(prefers-reduced-motion: reduce)', () => {
            gsap.set(cards, {
                xPercent: 0,
                opacity: 1,
                filter: 'blur(0px)',
            });
        });

        media.add('(prefers-reduced-motion: no-preference)', () => {
            const ctx = gsap.context(() => {
                gsap.fromTo(
                    cards,
                    {
                        xPercent: DUE_STATISTICS_SUMMARY_ENTRY_X_PERCENT,
                        opacity: 0,
                        filter: `blur(${DUE_STATISTICS_SUMMARY_ENTRY_BLUR_PX}px)`,
                    },
                    {
                        xPercent: 0,
                        opacity: 1,
                        filter: 'blur(0px)',
                        duration: DUE_STATISTICS_SUMMARY_ENTRY_DURATION_S,
                        ease: 'power3.out',
                        stagger: DUE_STATISTICS_SUMMARY_ENTRY_STAGGER_S,
                        force3D: true,
                        clearProps: 'transform,filter',
                    },
                );
            }, container);

            return () => ctx.revert();
        });

        return () => media.revert();
    }, []);

    return {
        summaryCardsContainerRef,
        onSelecionarModelo: toggleModelo,
        ui: {
            modeloSelecionado: modeloScope,
            totalOficios: data?.total_oficios ?? 0,
            totalOficiosV2: data?.total_oficios_v2 ?? 0,
            totalOficiosV1: data?.total_oficios_v1 ?? 0,
            valorLiquidoTotal: data?.valor_liquido_total ?? 0,
            oficiosEmDeadline: data?.oficios_em_deadline ?? 0,
            tribunaisUnicos: data?.tribunais_unicos ?? 0,
            isLoading,
        },
    };
}

