} from '../utils';

export interface TArquivamentosScreenVM {
    isLoading: boolean;
    isFetching: boolean;
    filteredItems: TDueDiligenceDetailedCardItem[];
    totalItems: number;
    getPendenciasData: typeof getPendenciasData;
    getObsCount: typeof getObsCount;
    getCessionariosLista: ReturnType<typeof useCessionarioDialogState>['getLista'];
    getTotalPctCessao: ReturnType<typeof useCessionarioDialogState>['getTotalPctCessaoForItem'];
    getIdwallStatus: typeof getIdwallStatus;
    getEscrituraStatus: (item: TDueDiligenceDetailedCardItem) => string | null;
    handlers: TDueCardScreenHandlers;
    page: number;
    totalPages: number;
    hasNextPage: boolean;
    hasPreviousPage: boolean;
    goToNextPage: () => void;
    goToPreviousPage: () => void;
    setPage: (page: number) => void;
    rootRef: React.RefObject<HTMLDivElement | null>;
}

export interface UseViewModelArquivamentosScreenParams {
    service: IArquivamentosScreenService;
    cessionarioService: CessionarioService;
}

export function useViewModelArquivamentosScreen(
    params: UseViewModelArquivamentosScreenParams,
): TArquivamentosScreenVM {
    const rootRef = useRef<HTMLDivElement | null>(null);
    const openObservationSheet = useDueDiligenceStore((state) => state.openObservationSheet);
    const router = useRouter();
    const {
        page,
        setPage,
        operationalListApiFilters: apiFilters,
        listQueryFingerprint,
    } = useOperationalListFilterQueryState();
    const [pageSize, setPageSize] = useState(10);
    const isFirstPageRender = useRef(true);
    const { service, cessionarioService } = params;

    const { data, isLoading, isFetching } = useQuery<
        PaginatedResponse<TDueDiligenceDetailedCardItem>
    >({
        queryKey: ['due-diligence', 'arquivados', 'items', page, listQueryFingerprint],
        queryFn: () => service.get(page, apiFilters),
    });

    useEffect(() => {
        if (
            data?.results?.length &&
            (data.next || page === 1) &&
            data.results.length !== pageSize
        ) {
            setPageSize(data.results.length);
        }
    }, [data, page, pageSize]);

    const items = useMemo(() => data?.results ?? [], [data?.results]);
    const totalItems = data?.count ?? 0;

    const totalPages = Math.max(1, Math.ceil(totalItems / Math.max(1, pageSize)));
    const hasNextPage = Boolean(data?.next);
    const hasPreviousPage = Boolean(data?.previous);

    const prefetchNextPage = useCallback(
        async (fromPage = page) => {
            if (!hasNextPage) return;
            const nextPage = fromPage + 1;
            await queryClient.prefetchQuery({
                queryKey: ['due-diligence', 'arquivados', 'items', nextPage, listQueryFingerprint],
                queryFn: () => service.get(nextPage, apiFilters),
            });
        },
        [apiFilters, hasNextPage, listQueryFingerprint, page, service],
    );

    useEffect(() => {
        void prefetchNextPage();
    }, [prefetchNextPage]);

    useEffect(() => {
        if (isFirstPageRender.current) {
            isFirstPageRender.current = false;
            return;
        }

        scrollToTop(rootRef.current);
    }, [page]);

    const cessionarioDialog = useCessionarioDialogState(items);
    const { resolveEscrituraStatus } = useEscrituraPublicaDialogState();

    const goToNextPage = () => {
        if (!hasNextPage || isFetching) return;
        void setPage(page + 1);
    };

    const goToPreviousPage = () => {
        if (!hasPreviousPage || isFetching || page <= 1) return;
        void setPage(page - 1);
    };

    const handlers = useMemo(() => {
        return cessionarioDialog.patchHandlers({
            ...createDueCardScreenHandlers({ router, items, openObservationSheet }),
            onRemoverCessionario: async (itemId: string, cessId: string) => {
                try {
                    await cessionarioService.deleteCessionario(itemId, cessId);
                    sendToastMessage({
                        title: 'Sucesso',
                        description: 'Cessionário desvinculado com sucesso',
                        type: 'success',
                    });
                    await queryClient.invalidateQueries({
                        queryKey: ['due-diligence'],
                        refetchType: 'all',
                    });
                } catch (error) {
                    console.error('Erro ao desvincular cessionário:', error);
                    sendToastMessage({
                        title: 'Erro ao desvincular cessionário',
                        description: 'Tente novamente em instantes.',
                        type: 'error',
                    });
                    throw error;
                }
            },
            onEscrituraPublica: (item) => {
                useDueDiligenceStore.getState().openEscrituraDialog(item);
            },
        });
    }, [
        router,
        items,
        openObservationSheet,
        cessionarioDialog,
        cessionarioService,
    ]);

    return {
        isLoading,
        isFetching,
        filteredItems: items,
        totalItems,
        getPendenciasData,
        getObsCount,
        getCessionariosLista: cessionarioDialog.getLista,
        getTotalPctCessao: cessionarioDialog.getTotalPctCessaoForItem,
        getIdwallStatus,
        getEscrituraStatus: resolveEscrituraStatus,
        handlers,
        page,
        totalPages,
        hasNextPage,
        hasPreviousPage,
        goToNextPage,
        goToPreviousPage,
        setPage: (nextPage) => void setPage(nextPage),
        rootRef,
    };
}

